DROP TABLE IF EXISTS `monitor_enterprise_daily_usage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monitor_enterprise_daily_usage` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `stat_date` date NOT NULL COMMENT '自然日，Asia/Shanghai [00:00,次日00:00)',
  `enterprise_id` bigint NOT NULL COMMENT 'tenant_enterprise.id',
  `processed_workorder_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '当日处理完成的非删除工单数',
  `request_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '当日企业鉴权业务API请求次数',
  `ocr_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '当日实际发起的OCR供应商调用次数',
  `new_customer_count` bigint unsigned NOT NULL DEFAULT '0' COMMENT '当日新增且未删除的下游商户数',
