  `is_finalized` tinyint NOT NULL DEFAULT '0' COMMENT '0当日滚动值 1自然日结束后的终值',
  `calculated_at` datetime DEFAULT NULL COMMENT '计算型指标最近重算时间',
  `finalized_at` datetime DEFAULT NULL COMMENT '自然日终值确认时间',
  `last_flushed_at` datetime DEFAULT NULL COMMENT 'API/OCR Redis绝对值最近覆盖写库时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_monitor_enterprise_usage_day` (`stat_date`,`enterprise_id`),
  KEY `idx_monitor_enterprise_usage_query` (`enterprise_id`,`stat_date`)
) ENGINE=InnoDB AUTO_INCREMENT=162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业每日用量统计';
