CREATE TABLE `saas_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `enterprise_id` bigint NOT NULL COMMENT '企业ID',
  `plan_id` bigint DEFAULT NULL COMMENT '当前或最近一次套餐',
  `order_id` bigint DEFAULT NULL COMMENT '最近一次生效订单',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0未订阅 1生效中 2已过期 3已暂停 4已取消',
  `suspend_reason` varchar(32) DEFAULT NULL COMMENT '暂停原因：ARREARS欠费、MANUAL人工、RISK_CONTROL风控',
  `suspended_at` datetime DEFAULT NULL COMMENT '最近一次暂停时间',
  `resumed_at` datetime DEFAULT NULL COMMENT '最近一次从欠费暂停恢复时间',
  `user_limit` int NOT NULL DEFAULT '0' COMMENT '当前可启用成员上限',
  `workorder_limit` int NOT NULL DEFAULT '0' COMMENT '当前订阅包含的工单数量额度',
  `ocr_quota` int NOT NULL DEFAULT '0' COMMENT '当前周期OCR额度',
  `request_quota` int NOT NULL DEFAULT '0' COMMENT '当前周期请求额度',
  `start_at` datetime DEFAULT NULL COMMENT '生效时间',
  `end_at` datetime DEFAULT NULL COMMENT '到期时间',
  `auto_renew_enabled` tinyint NOT NULL DEFAULT '0' COMMENT 'auto renew enabled',
  `auto_renew_plan_id` bigint DEFAULT NULL COMMENT 'auto renew plan id',
  `next_renew_at` datetime DEFAULT NULL COMMENT 'next renew time',
  `last_renew_order_id` bigint DEFAULT NULL COMMENT 'last renew order id',
  `cancel_auto_renew_at` datetime DEFAULT NULL COMMENT 'cancel auto renew time',
  `created_at` datetime DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_saas_subscription_enterprise` (`enterprise_id`),
  KEY `idx_saas_subscription_arrears` (`status`,`suspend_reason`,`end_at`,`enterprise_id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业订阅表';
