  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_saas_visitor_lead_no` (`lead_no`),
  KEY `idx_saas_visitor_lead_created` (`deleted`,`created_at`,`id`),
  CONSTRAINT `chk_saas_visitor_lead_intent_codes` CHECK (((json_type(`intent_codes`) = _utf8mb4'ARRAY') and (json_length(`intent_codes`) between 1 and 3) and (json_contains(json_array(_utf8mb4'TRIAL',_utf8mb4'DEMO',_utf8mb4'CUSTOM_COOPERATION'),`intent_codes`) = 1))),
  CONSTRAINT `chk_saas_visitor_lead_monthly_orders` CHECK ((`expected_monthly_orders` >= 0)),
  CONSTRAINT `chk_saas_visitor_lead_role` CHECK ((`role_code` in (_utf8mb4'OPC_AGENT',_utf8mb4'CAR_DEALER',_utf8mb4'INSURANCE_AGENCY',_utf8mb4'OTHER')))
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='SaaS门户官网游客线索';
